// TaskInviteState 任务创建邀请状态（词汇表「任务创建邀请」）
type TaskInviteState string

// TaskReceipt 一条待接收项／接收记录：未确认为待接收项，已确认为接收记录（接收方、任务、生成时间、确认时间）
type TaskReceipt struct {
	// ConfirmedAt 确认接收时间；未确认时不返回
	ConfirmedAt *time.Time `json:"confirmedAt,omitempty"`
	DisplayName string     `json:"displayName"`
	GeneratedAt time.Time  `json:"generatedAt"`
	Id          int64      `json:"id"`
	UserId      int64      `json:"userId"`
}

// TaskRelation 协作关系摘要中的一条直接协作关系（词汇表「协作关系摘要」；PRD §7.5）；不插入交付物中间节点，同一对方任务同一关系类型合并为一条
type TaskRelation struct {
	// EdgeType 交付物边类型（PRD §4.3；词汇表「交付物边」）
	EdgeType EdgeType `json:"edgeType"`

	// KrDescription 对方任务所属 KR 描述（派生字段）
	KrDescription string `json:"krDescription"`

	// OwnerName 对方任务负责人姓名（派生字段）
	OwnerName string `json:"ownerName"`

	// Ready 该关系是否就绪（AC-48；合并后全部边就绪才为真）
	Ready bool `json:"ready"`

	// TaskId 对方任务
	TaskId   int64  `json:"taskId"`
	TaskName string `json:"taskName"`

	// TaskStatusLabel 对方任务状态显示文案（AC-04；派生字段）
	TaskStatusLabel string `json:"taskStatusLabel"`
}

// TaskStatus 任务生命周期状态（词汇表「任务生命周期状态」）；页面主状态汇总，审批原始状态在审批单中
type TaskStatus string

